const lockDeliveringAgentRun = `-- name: LockDeliveringAgentRun :one
SELECT account_id::text AS account_id,(cancel_requested_at IS NOT NULL)::boolean AS cancel_requested FROM agent_runs
 WHERE id=$1::text::uuid AND state='delivering' FOR UPDATE
`

type LockDeliveringAgentRunRow struct {
	AccountID       string
	CancelRequested bool
}

// Settling locks the run first, so the last two deliveries of a run to end
// cannot both miss each other.
func (q *Queries) LockDeliveringAgentRun(ctx context.Context, db DBTX, runID string) (LockDeliveringAgentRunRow, error) {
	row := db.QueryRow(ctx, lockDeliveringAgentRun, runID)
	var i LockDeliveringAgentRunRow
	err := row.Scan(&i.AccountID, &i.CancelRequested)
	return i, err
}

